import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`ai-seo`,heroTitle:e({defaultMessage:`Track your AI visibility in minutes`,id:`57042bd314`}),heroSubtitle:e({defaultMessage:`Perplexity Computer checks your brand across ChatGPT, Gemini, and Copilot, and builds your AI SEO playbook — automatically.`,id:`5ea18e7f8e`}),inputUrlCta:e({defaultMessage:`Scan my visibility`,id:`575d416073`}),inputUrlPlaceholder:`www.yourcompany.com`,inputUrlPrefill:e({defaultMessage:`Go to {url} and perform a full AI visibility audit. 1) Identify the brand’s top 20 keywords and topics based on the site’s content. 2) Search each keyword across ChatGPT, Gemini, and Microsoft Copilot to check whether the brand appears in AI-generated answers. 3) Record which competitors are cited instead for each query. 4) Score overall AI visibility across all three engines. 5) Deliver a prioritized playbook with specific actions to get the brand cited in AI-generated answers — including content changes, authority signals, and structured data recommendations.`,id:`057456bbe2`}),heroOverlaySteps:[e({defaultMessage:`Crawling your site to extract top keywords and brand positioning`,id:`e3e0a60417`}),e({defaultMessage:`Querying ChatGPT, Gemini, and Copilot for each of your target keywords`,id:`9dc12281c7`}),e({defaultMessage:`Identifying which competitors AI engines cite instead of you`,id:`6afcc74b2a`}),e({defaultMessage:`Visibility scores, competitor gaps, and AI SEO playbook — ready to execute`,id:`d858d121df`})],generatingSteps:[e({defaultMessage:`Visiting {url} to extract your brand, keywords, and content footprint`,id:`c6c06df7d7`}),e({defaultMessage:`Designing an agent to query ChatGPT, Gemini, and Copilot for your top keywords`,id:`3d1a986fa1`}),e({defaultMessage:`Configuring competitor citation tracking and visibility scoring across all three engines`,id:`9e84f6ef74`}),e({defaultMessage:`Setting up your AI SEO playbook with prioritized actions and monitoring`,id:`3e1c4c9448`})],featureSectionTitle:e({defaultMessage:`From URL to AI visibility playbook`,id:`3a74a86a59`}),featureCardTitles:[e({defaultMessage:`Connects to your marketing stack`,id:`77b68c6835`}),e({defaultMessage:`Outputs you can act on`,id:`fcba620401`})],featureCardDescriptions:[e({defaultMessage:`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,id:`4f88823b40`}),e({defaultMessage:`Google Search Console, Analytics, Ahrefs, Notion, Google Sheets — Computer plugs into your tools so AI visibility tracking and traditional SEO work in one workflow.`,id:`0a39f24174`}),e({defaultMessage:`AI visibility scorecards. Competitor citation maps. Keyword-by-keyword engine breakdowns. A prioritized playbook to get your brand into AI-generated answers.`,id:`dcbcbf3b2d`})],capabilitySectionTitle:e({defaultMessage:`Your AI SEO team, on autopilot`,id:`345a6dcab0`}),capabilitySectionSubtitle:e({defaultMessage:`Paste your URL, step away, come back to a complete AI visibility strategy.`,id:`3428a51fa9`}),capabilityCards:[{title:e({defaultMessage:`AI Visibility Audit`,id:`9fadcceb39`}),description:e({defaultMessage:`Computer can query ChatGPT, Gemini, and Copilot for your top keywords — and report exactly where your brand shows up and where it doesn’t.`,id:`1d41b28486`})},{title:e({defaultMessage:`Competitor Citation Analysis`,id:`07b4ace35f`}),description:e({defaultMessage:`Computer can identify which competitors AI engines cite instead of you — and surface the content and authority gaps driving those citations.`,id:`8d0b3bfa21`})},{title:e({defaultMessage:`Playbook Generation`,id:`2c44b1a9d2`}),description:e({defaultMessage:`Computer can build a prioritized action plan — content rewrites, structured data fixes, authority signals — tailored to each AI engine’s citation patterns.`,id:`4eb21e0bcb`})},{title:e({defaultMessage:`Connect Your Tools`,id:`3eebc3280f`}),description:e({defaultMessage:`Computer can read from Google Search Console, Analytics, Ahrefs, Notion, and more — build workflows across your entire SEO and content stack.`,id:`11b3b511dd`})},{title:e({defaultMessage:`Remember & Learn`,id:`39fe640626`}),description:e({defaultMessage:`Computer can remember your keywords, competitors, and past visibility scores across sessions — so every audit tracks your progress over time.`,id:`01f9bd5c6c`})},{title:e({defaultMessage:`Monitor & Alert`,id:`a1e1703c18`}),description:e({defaultMessage:`Computer can re-check your AI visibility weekly and flag when competitors overtake you or new citation opportunities appear.`,id:`7929b8686c`})}]});export{n as default};
